<script setup>
import { nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import L from 'leaflet'; import 'leaflet/dist/leaflet.css'; import '../assets/courier-map.css'; import '../assets/courier-labels.css'; import '../assets/courier-marker-icons.css'; import '../assets/courier-map-tracking.css'
const props = defineProps({ restaurant: { type: Object, default: null }, destination: { type: Object, default: null }, state: { type: String, default: '' }, courier: { type: Object, default: null } }); const emit = defineEmits(['route']); const element = ref(null); const routeInfo = ref(null); const routeError = ref(false); let map; let markers = []; let routeLayer; let hasInitialView = false; let previousCourier = null; let previousState = ''; let drawVersion = 0
function point(source, latKey, lonKey) { const lat = Number(source?.[latKey]); const lon = Number(source?.[lonKey]); return Number.isFinite(lat) && Number.isFinite(lon) ? [lat, lon] : null }
function icon(type) { const svg = type === 'pickup' ? '<path d="M4 10h16M6 10l2-5h8l2 5M7 10v8h10v-8M10 14h4"/>' : type === 'courier' ? '<circle cx="7" cy="17" r="2"/><circle cx="17" cy="17" r="2"/><path d="M7 17l3-8h4l3 8M10 9l-2-3M10 9h5l2 3"/>' : '<path d="M3 11l9-7 9 7M5 10v9h14v-9M9 19v-5h6v5"/>'; return L.divIcon({ className: `courier-map-marker courier-map-marker--${type}`, html: `<svg viewBox="0 0 24 24" aria-hidden="true">${svg}</svg>`, iconSize: [36, 36], iconAnchor: [18, 18] }) }
async function draw() { if (!map) return; const version = ++drawVersion; markers.forEach((item) => item.remove()); markers = []; routeLayer?.remove(); routeInfo.value = null; emit('route', null); routeError.value = false; const pickup = point(props.restaurant, 'pos_y', 'pos_x'); const destination = props.destination || props.restaurant?.__destination; const delivery = point(destination, 'latitud', 'longitud'); const courier = point(props.courier, 'pos_y', 'pos_x'); const routeOrigin = courier || pickup; const routeTarget = props.state === 'ASIGNADO' ? pickup : delivery; const points = [pickup, delivery, courier].filter(Boolean); if (!points.length) return; const pickupLabel = `Recogida · ${props.restaurant?.nombre || 'Restaurante'}`; const deliveryLabel = `Entrega · ${destination?.detalle || destination?.zonas?.nombre || 'Cliente'}`; const courierLabel = 'Ubicación del repartidor'; if (pickup) markers.push(L.marker(pickup, { icon: icon('pickup') }).addTo(map).bindPopup(pickupLabel).bindTooltip(pickupLabel, { permanent: true, direction: 'top', offset: [0, -27] })); if (delivery) markers.push(L.marker(delivery, { icon: icon('delivery') }).addTo(map).bindPopup(deliveryLabel).bindTooltip(deliveryLabel, { permanent: true, direction: 'top', offset: [0, -27] })); if (courier) { const courierMarker = L.marker(courier, { icon: icon('courier') }).addTo(map).bindPopup(courierLabel).bindTooltip(courierLabel, { permanent: true, direction: 'top', offset: [0, -27] }); if (previousCourier && (previousCourier[0] !== courier[0] || previousCourier[1] !== courier[1])) { const start = previousCourier; const started = performance.now(); const animate = (now) => { const progress = Math.min((now - started) / 2200, 1); const eased = progress < .5 ? 2 * progress * progress : 1 - Math.pow(-2 * progress + 2, 2) / 2; courierMarker.setLatLng([start[0] + (courier[0] - start[0]) * eased, start[1] + (courier[1] - start[1]) * eased]); if (progress < 1) requestAnimationFrame(animate) }; requestAnimationFrame(animate) } markers.push(courierMarker); previousCourier = courier } if (!hasInitialView || props.state !== previousState) { if (points.length > 1) map.fitBounds(L.latLngBounds(points), { padding: [30, 30], maxZoom: 15 }); else map.setView(points[0], 15); hasInitialView = true; previousState = props.state } if (!routeOrigin || !routeTarget) return; try { const response = await fetch(`https://router.project-osrm.org/route/v1/driving/${routeOrigin[1]},${routeOrigin[0]};${routeTarget[1]},${routeTarget[0]}?overview=full&geometries=geojson`); if (!response.ok) throw new Error('route'); const data = await response.json(); if (version !== drawVersion) return; const route = data.routes?.[0]; if (!route) throw new Error('route'); routeLayer = L.geoJSON(route.geometry, { style: { color: '#f20552', weight: 5, opacity: .8 } }).addTo(map); routeInfo.value = { km: route.distance / 1000, min: route.duration / 60 }; emit('route', routeInfo.value) } catch { if (version === drawVersion) { routeError.value = true; emit('route', null) } } }
onMounted(async () => { await nextTick(); map = L.map(element.value, { zoomControl: false, zoomSnap: .5 }); L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Base/MapServer/tile/{z}/{y}/{x}', { attribution: 'Tiles &copy; Esri', maxZoom: 16 }).addTo(map); L.tileLayer('https://server.arcgisonline.com/ArcGIS/rest/services/Canvas/World_Light_Gray_Reference/MapServer/tile/{z}/{y}/{x}', { attribution: 'Labels &copy; Esri', maxZoom: 16, pane: 'overlayPane' }).addTo(map); await draw(); setTimeout(() => map?.invalidateSize(), 80) }); watch(() => [props.restaurant, props.destination, props.courier, props.state], draw, { deep: true }); onBeforeUnmount(() => map?.remove())
</script>
<template><div class="courier-request-map"><div ref="element" class="courier-request-map__canvas" /><p v-if="routeInfo" class="courier-map-info">{{ routeInfo.km.toFixed(1) }} km · {{ Math.round(routeInfo.min) }} min estimados por carretera</p><p v-else-if="routeError" class="courier-map-info">No se pudo calcular la ruta; se muestran los puntos disponibles.</p><p v-else-if="!restaurant?.pos_y || !restaurant?.pos_x || !destination?.latitud || !destination?.longitud" class="courier-map-info">Faltan coordenadas para mostrar ambos puntos.</p></div></template>
